import { Scalekit } from '@scalekit-sdk/node';
import fs from 'fs';
import path from 'path';

// Read trial_id from file
const trialId = fs.readFileSync('/logs/trial_id', 'utf-8').trim();

console.log('Trial ID:', trialId);

// Initialize Scalekit instance
// Using environment variables for configuration
const scalekit = new Scalekit({
  environmentId: process.env.SCALEKIT_ENVIRONMENT_ID,
  secretKey: process.env.SCALEKIT_SECRET_KEY,
});

async function manageOrganizations() {
  try {
    console.log('Creating organization...');

    // Create a new organization
    const externalId = `ext_org_${trialId}`;
    const newOrg = await scalekit.organization.createOrganization({
      display_name: 'Harbor Test Org',
      external_id: externalId,
    });

    console.log('Organization created successfully!');
    console.log('Organization ID:', newOrg.id);
    console.log('Organization Name:', newOrg.display_name);
    console.log('External ID:', newOrg.external_id);

    // List all organizations
    console.log('\nListing all organizations...');
    const orgs = await scalekit.organization.listOrganizations();

    console.log(`Found ${orgs.length} organizations:`);
    orgs.forEach((org, index) => {
      console.log(`${index + 1}. ${org.display_name} (ID: ${org.id}, External ID: ${org.external_id})`);
    });

    // Find the created organization in the list
    const createdOrg = orgs.find(org => org.id === newOrg.id);

    if (createdOrg) {
      console.log('\n✓ Created organization found in the list!');
    } else {
      console.log('\n⚠ Warning: Created organization not found in the list');
    }

    // Write the organization ID to file
    const orgIdPath = '/home/user/scalekit-orgs/org_id.txt';
    fs.writeFileSync(orgIdPath, newOrg.id, 'utf-8');
    console.log(`\n✓ Organization ID written to ${orgIdPath}`);

  } catch (error) {
    console.error('Error managing organizations:', error);
    process.exit(1);
  }
}

// Run the function
manageOrganizations();

